//   +3    M2  P2 = P | P*C' | P*imm1;  Q = C' * (+-D)  (a second multiplier)
//   +3    AD  R = P2 | P2+Q | P2+C' | P2-B | P2+imm2 | P2+D
//   +s    S   S = R | exp | sigmoid | silu | rsqrt | sqrt | sqrt(softplus) | gate
