            if (ld_e) begin
                ldp_bank <= ldbank_e;
                for (s = 0; s < 5; s = s + 1) begin
                    g0 = {AW{1'b0}};
                    g1 = {AW{1'b0}};
                    g2 = {AW{1'b0}};
                    for (k = 0; k < LN; k = k + 1)
                        if (lane_id[k]) begin
                            if (k < G1)      g0 = g0 + ldc_e[(s*LN + k)*AW +: AW];
                            else if (k < G2) g1 = g1 + ldc_e[(s*LN + k)*AW +: AW];
                            else             g2 = g2 + ldc_e[(s*LN + k)*AW +: AW];
                        end
                    ldp_0[s] <= g0;
                    ldp_1[s] <= g1;
                    ldp_2[s] <= g2;
                end
            end
            if (ldp_v) begin
                ldq_bank <= ldp_bank;
                for (s = 0; s < 5; s = s + 1) begin
                    ldq_01[s] <= ldp_0[s] + ldp_1[s];
                    ldq_2[s] <= ldp_2[s];
                end
            end
            if (ldq_v)
                for (s = 0; s < 5; s = s + 1)
                    if (ldq_bank) off1[s] <= ldq_01[s] + ldq_2[s]; else off0[s] <= ldq_01[s] + ldq_2[s];
        end
    end else begin : g_ld3k
        // the same three cycles on keep-prefix adders: a group's (at most 4) masked terms in a two-level tree
        reg          ldp_v, ldq_v, ldp_bank, ldq_bank;
        always @(posedge clk_stage[0] or negedge rst_n) begin
            if (!rst_n) begin ldp_v <= 1'b0; ldq_v <= 1'b0; end
            else begin ldp_v <= ld_e; ldq_v <= ldp_v; end
        end
        always @(posedge clk_stage[0]) begin
            if (ld_e) ldp_bank <= ldbank_e;
            if (ldp_v) ldq_bank <= ldp_bank;
        end
        genvar ss, jj, kk;
        wire [5*AW-1:0] s_bus;                         // stream ss's offset, at the third cycle
        integer s;
        always @(posedge clk_stage[0])
            if (ldq_v)
                for (s = 0; s < 5; s = s + 1)
                    if (ldq_bank) off1[s] <= s_bus[s*AW +: AW]; else off0[s] <= s_bus[s*AW +: AW];
        for (ss = 0; ss < 5; ss = ss + 1) begin : g_s
            wire [3*AW-1:0] grp;                       // the three group sums of stream ss
            for (jj = 0; jj < 3; jj = jj + 1) begin : g_j
                localparam integer LO = (jj == 0) ? 0 : (jj == 1) ? G1 : G2;
                localparam integer HI = (jj == 0) ? G1 : (jj == 1) ? G2 : LN;
                wire [4*AW-1:0] t;                     // the group's masked terms, zero-padded to 4
                for (kk = 0; kk < 4; kk = kk + 1) begin : g_t
                    if (LO + kk < HI) begin : g_on
                        assign t[kk*AW +: AW] = lane_id[LO + kk] ? ldc_e[(ss*LN + LO + kk)*AW +: AW] : {AW{1'b0}};
                    end else begin : g_off
                        assign t[kk*AW +: AW] = {AW{1'b0}};
                    end
                end
                wire [AW-1:0] s01, s23;
                wire [2:0]    unused_c;
                if (HI - LO > 2) begin : g_4
                    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_a (.a(t[0 +: AW]), .b(t[AW +: AW]), .cin(1'b0), .s(s01), .cout(unused_c[0]));
                    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_b (.a(t[2*AW +: AW]), .b(t[3*AW +: AW]), .cin(1'b0), .s(s23), .cout(unused_c[1]));
                    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_c (.a(s01), .b(s23), .cin(1'b0), .s(grp[jj*AW +: AW]), .cout(unused_c[2]));
                end else if (HI - LO == 2) begin : g_2
                    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_a (.a(t[0 +: AW]), .b(t[AW +: AW]), .cin(1'b0), .s(grp[jj*AW +: AW]), .cout(unused_c[0]));
                    assign {s01, s23, unused_c[2:1]} = 0;
                end else begin : g_1
                    assign grp[jj*AW +: AW] = t[0 +: AW];
                    assign {s01, s23, unused_c} = 0;
                end
            end
            reg  [AW-1:0] p0, p1, p2, q01, q2;
            wire [AW-1:0] s_01, s_all;
            wire [1:0]    unused_q;
            ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_q (.a(p0), .b(p1), .cin(1'b0), .s(s_01), .cout(unused_q[0]));
            ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(1)) u_o (.a(q01), .b(q2), .cin(1'b0), .s(s_all), .cout(unused_q[1]));
            assign s_bus[ss*AW +: AW] = s_all;
            always @(posedge clk_stage[0]) begin
                if (ld_e) begin p0 <= grp[0 +: AW]; p1 <= grp[AW +: AW]; p2 <= grp[2*AW +: AW]; end
                if (ldp_v) begin q01 <= s_01; q2 <= p2; end
            end
        end
    end endgenerate

    // ---- F0: liveness, addresses ------------------------------------------------------------------
    wire ol_ge, il_ge;
    ot_hdc_kge__d4g_pgslice #(.W(CW), .K(K)) u_olg (.a(ol_e), .b(no_e), .ge(ol_ge));
    ot_hdc_kge__d4g_pgslice #(.W(CW), .K(K)) u_ilg (.a(il_e), .b(ni_e), .ge(il_ge));
    wire live0 = emit_e && lin_e && !ol_ge && !il_ge;
    // (il << 4) + row[3:0] is the concatenation {il, row[3:0]}
    wire [AW-1:0] kvt, kvt1, vi_sum;
    wire [2:0]    unused_c1;
    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(K)) u_kv1 (.a(obase_e), .b((row_e >> 4) << KVT_SH), .cin(1'b0), .s(kvt1), .cout(unused_c1[0]));
    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(K)) u_kv2 (.a(kvt1), .b({il_e[AW-5:0], row_e[3:0]}), .cin(1'b0), .s(kvt), .cout(unused_c1[1]));
    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(K)) u_via (.a(aibase_e), .b((aind_e == IND_I) ? il_e[AW-1:0] : ol_e[AW-1:0]), .cin(1'b0),
                                        .s(vi_sum), .cout(unused_c1[2]));
    reg          f_v, f_g, f_par;
    reg [AW-1:0] f_a, f_b, f_c, f_d, f_o;
    reg [7:0]    f_src;
    reg          f_cpair;
    always @(posedge clk_stage[0] or negedge rst_n) begin
        if (!rst_n) begin f_v <= 1'b0; vi_re <= 1'b0; end
        else begin f_v <= live0; vi_re <= live0 && (aind_e != IND_NONE); end
    end
    always @(posedge clk_stage[0]) begin
        f_g <= (aind_e != IND_NONE);
        f_a <= sum_e[0 +: AW];
        f_b <= sum_e[AW +: AW];
        f_c <= sum_e[2*AW +: AW];
        f_d <= sum_e[3*AW +: AW];
        f_o <= (dst_e == DST_KVT) ? kvt : sum_e[4*AW +: AW];
        f_par <= il_e[0];
        f_src <= srcs_e;
        f_cpair <= cpair_e;
        vi_addr <= vi_sum;
    end
    // Pinned SRAM adds two index metadata edges before G1, not an address reinterpretation.
    wire fg_v, fg_g, fg_par, fg_cpair;
    wire [AW-1:0] fg_a, fg_b, fg_c, fg_d, fg_o;
    wire [7:0] fg_src;
    wire [4:0] fg_sh;
    reg [4:0] f_sh;
    always @(posedge clk_stage[0]) f_sh <= gsh_e;
    generate if (FETCH_EXTRA_EDGES > 0) begin:g_index_edge
        reg [FETCH_EXTRA_EDGES-1:0] valid;
        reg [5*AW+15:0] payload[0:FETCH_EXTRA_EDGES-1];
        integer ix;
        always @(posedge clk_stage[0] or negedge rst_n)
            if (!rst_n) valid <= 0; else valid <= (valid << 1) | f_v;
        always @(posedge clk_stage[0]) begin
            payload[0] <= {f_g,f_par,f_cpair,f_a,f_b,f_c,f_d,f_o,f_src,f_sh};
            for(ix=1;ix<FETCH_EXTRA_EDGES;ix=ix+1)payload[ix]<=payload[ix-1];
        end
        assign fg_v=valid[FETCH_EXTRA_EDGES-1];
        assign {fg_g,fg_par,fg_cpair,fg_a,fg_b,fg_c,fg_d,fg_o,fg_src,fg_sh}=payload[FETCH_EXTRA_EDGES-1];
    end else begin:g_index_direct
        assign {fg_v,fg_g,fg_par,fg_cpair,fg_a,fg_b,fg_c,fg_d,fg_o,fg_src,fg_sh}=
               {f_v,f_g,f_par,f_cpair,f_a,f_b,f_c,f_d,f_o,f_src,f_sh};
    end endgenerate
    // ---- G1, G2: a gathered A (index from the vector memory, scaled by a power of two) ---------------
    reg          g1_v, g2_v, g1_par, g2_par, g1_cpair, g2_cpair;
    reg [AW-1:0] g1_a, g1_b, g1_c, g1_d, g1_o, g2_a, g2_b, g2_c, g2_d, g2_o;
    reg [7:0]    g1_src, g2_src;
    reg [4:0]    g1_sh;
    always @(posedge clk_stage[0] or negedge rst_n) begin
        if (!rst_n) begin g1_v <= 1'b0; g2_v <= 1'b0; end
        else begin g1_v <= fg_v && fg_g; g2_v <= g1_v; end
    end
    wire [AW-1:0] g2_sum;
    wire          unused_c2;
    ot_hdc_kadd__d4g_pgslice #(.W(AW), .K(K)) u_g2a (.a(g1_a), .b(vi_q[AW-1:0] << g1_sh), .cin(1'b0), .s(g2_sum), .cout(unused_c2));
    always @(posedge clk_stage[0]) begin
        g1_a <= fg_a; g1_b <= fg_b; g1_c <= fg_c; g1_d <= fg_d; g1_o <= fg_o; g1_par <= fg_par; g1_src <= fg_src;
        g1_cpair <= fg_cpair; g1_sh <= fg_sh;
        g2_a <= g2_sum;
        g2_b <= g1_b; g2_c <= g1_c; g2_d <= g1_d; g2_o <= g1_o; g2_par <= g1_par; g2_src <= g1_src;
        g2_cpair <= g1_cpair;
    end
    // ---- memory reads: the F0 vector, or a gather vector two cycles later ------------------------------
    wire          mr_nv = f_v && !f_g;
    wire          mr_v  = mr_nv || g2_v;
    wire [AW-1:0] mr_a  = g2_v ? g2_a : f_a;
    wire [AW-1:0] mr_c  = (g2_v ? g2_cpair : f_cpair) ? (mr_a ^ {{(AW-1){1'b0}}, 1'b1}) : (g2_v ? g2_c : f_c);
    wire [7:0]    mr_src = g2_v ? g2_src : f_src;
    assign rd_addr = {g2_v ? g2_d : f_d, mr_c, g2_v ? g2_b : f_b, mr_a};
    assign rd_re = {4{mr_v}};
    assign rd_src = mr_src;
    // Exact read-tag extension: x_a..d capture the actual external SRAM q.
    reg m_v, x_v;
    reg [AW-1:0] m_o, x_o;
    reg m_par, x_par;
    wire mf_v, mf_par;
    wire [AW-1:0] mf_o;
    generate if (FETCH_EXTRA_EDGES > 0) begin:g_fetch_edge
        reg [FETCH_EXTRA_EDGES-1:0] v;
        reg [AW:0] tag[0:FETCH_EXTRA_EDGES-1];
        integer fx;
        always @(posedge clk_stage[0] or negedge rst_n)
            if (!rst_n) v <= 0; else v <= (v << 1) | mr_v;
        always @(posedge clk_stage[0]) begin
            tag[0] <= {g2_v ? g2_o : f_o, g2_v ? g2_par : f_par};
            for(fx=1;fx<FETCH_EXTRA_EDGES;fx=fx+1)tag[fx]<=tag[fx-1];
        end
        assign mf_v=v[FETCH_EXTRA_EDGES-1]; assign {mf_o,mf_par}=tag[FETCH_EXTRA_EDGES-1];
    end else begin:g_fetch_direct
        assign mf_v=mr_v;
        assign mf_o=g2_v ? g2_o : f_o;
        assign mf_par=g2_v ? g2_par : f_par;
    end endgenerate
    always @(posedge clk_stage[0] or negedge rst_n) begin
        if (!rst_n) begin m_v<=0; x_v<=0; end
        else begin m_v<=mf_v; x_v<=m_v; end
    end
    always @(posedge clk_stage[0]) begin
        m_o<=mf_o; m_par<=mf_par; x_o<=m_o; x_par<=m_par;
    end
    generate if (FETCH_EXTRA_EDGES < 0 || FETCH_EXTRA_EDGES > 4) begin:g_bad_fetch
        // 0 raw macro, 2 pinned bank, 4 pinned bank behind a pin-registered lane (ot_hbm_su_static_lane_pinreg__d4g_pgslice)
        ot_su_response_offset_must_be_0_to_4 u_trap();
    end endgenerate
    // ---- X: capture (the memories answered during the cycle before) --------------------------------------
    reg [31:0] x_a, x_b, x_c, x_d;
    always @(posedge clk_stage[0]) begin
        x_a <= rd_q[31:0]; x_b <= rd_q[63:32]; x_c <= rd_q[95:64]; x_d <= rd_q[127:96];
    end
    // ---- PRE ------------------------------------------------------------------------------------------
    // A' = min(relu(rnd?(A)), imm3), evaluated for the three values rnd?(A) can take (A itself, A truncated to
    // BF16, and truncated + one BF16 ulp) side by side and selected by the rounding decision, so no compare
    // waits for the rounding carry (bit-identical for all inputs: tools/w11_equiv_clip.ys; W11 timing fix)
    wire [31:0] a_t  = {x_a[31:16], 16'd0};
    wire [15:0] a_hi1;
    ot_hdc_kinc__d4g_pgslice #(.W(16), .K(K)) u_au (.a(x_a[31:16]), .inc(1'b1), .y(a_hi1));
    wire [31:0] a_u  = {a_hi1, 16'd0};
    wire        a_up = x_a[15] & ((|x_a[14:0]) | x_a[16]);
    // pre_a's compares, as prefix compares: okey(v) <= okey(imm3) for the three candidates, and +0 <= imm3
    wire [31:0] k_imm3 = okey(cx_imm3);
    wire        le_x, le_t, le_u, le_0;
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_lex (.a(k_imm3), .b(okey(x_a)), .ge(le_x));
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_let (.a(k_imm3), .b(okey(a_t)), .ge(le_t));
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_leu (.a(k_imm3), .b(okey(a_u)), .ge(le_u));
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_le0 (.a(k_imm3), .b(32'h80000000), .ge(le_0));
    wire [31:0] a_mx = pre_a2(x_a, cx_arelu, cx_amin, cx_imm3, le_x, le_0);
    wire [31:0] a_mt = pre_a2(a_t, cx_arelu, cx_amin, cx_imm3, le_t, le_0);
    wire [31:0] a_mu = pre_a2(a_u, cx_arelu, cx_amin, cx_imm3, le_u, le_0);
    wire [31:0] a_m  = !cx_arnd ? a_mx : a_up ? a_mu : a_mt;
    // clip(C, -imm3, imm3) = fmin(fmax(C, lo), hi) with its three comparisons side by side (bit-identical,
    // ties included: proven by tools/w11_equiv_clip.ys; the chained form was the lane's critical path, W11)
    wire [31:0] c_lo = {1'b1, cx_imm3[30:0]};
    wire        c_ge_lo, c_le_hi, c_lohi;
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_cgl (.a(okey(x_c)), .b(okey(c_lo)), .ge(c_ge_lo));
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_clh (.a(k_imm3), .b(okey(x_c)), .ge(c_le_hi));
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_clo (.a(k_imm3), .b(okey(c_lo)), .ge(c_lohi));
    wire [31:0] c_m = !cx_cclip ? x_c : c_ge_lo ? (c_le_hi ? x_c : cx_imm3) : (c_lohi ? c_lo : cx_imm3);
    reg  [31:0] p_a, p_b, p_c, p_d;
    reg  [AW-1:0] p_o;
    reg         p_v, p_par;
    always @(posedge clk_stage[0] or negedge rst_n) begin
        if (!rst_n) p_v <= 1'b0; else p_v <= x_v;
    end
    always @(posedge clk_stage[0]) begin
        p_a <= a_m; p_b <= x_b; p_c <= c_m; p_d <= x_d; p_o <= x_o; p_par <= x_par;
    end
    // ---- M1 ---------------------------------------------------------------------------------------------
    wire p_mul = (cp_m1 == M1_AB) || (cp_m1 == M1_AA) || (cp_m1 == M1_AIMM);
    wire p_div = (cp_m1 == M1_DIVB) || (cp_m1 == M1_DIVIMM);
    wire [31:0] mul1_y, byp1;
    wire f_m1;
    ot_hdc_qmul_lat__d4g_pgslice #(MLAT) u_m1 (clk_stage[1], rst_n, p_v && p_mul, p_a, (cp_m1 == M1_AB) ? p_b : (cp_m1 == M1_AA) ? p_a : cp_imm1,
                      mul1_y, f_m1);
    wire        ba_ge;                               // okey(p_a) >= okey(p_b), i.e. not (okey(p_b) > okey(p_a))
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(K)) u_mxb (.a(okey(p_a)), .b(okey(p_b)), .ge(ba_ge));
    wire [31:0] byp_in = (cp_m1 == M1_MAXB && !ba_ge) ? p_b : p_a;
    ot_hdc_delay__d4g_pgslice #(.W(32), .D(MLAT)) u_b1 (.clk(clk_stage[1]), .rst_n(rst_n), .d(byp_in), .q(byp1));
    localparam integer T1W = 32 * 3 + AW + 1;            // B, C', D, O, parity
    wire [T1W-1:0] t1;
    wire           v1;
    wire [31:0]    div1_y;
    wire           f_d1, c1;
    generate
        if (HAS_SFU != 0) begin : g_m1s
            ot_hdc_v41x_fdiv__d4g_pgslice u_d1 (.clk(clk_stage[1]), .rst_n(rst_n), .v(p_v && p_div), .a(p_a),
                                   .b((cp_m1 == M1_DIVB) ? p_b : cp_imm1), .y(div1_y), .vo(), .fault(f_d1));
            ot_hdc_v41x_ins__d4g_pgslice #(.W(T1W), .K(2), .DEPTHS({H_DIV, H_M}), .DMAX(19)) u_l1 (
                .clk(clk_stage[1]), .rst_n(rst_n), .v(p_v), .sel({p_div, !p_div}), .d({p_b, p_c, p_d, p_o, p_par}),
                .vo(v1), .q(t1), .coll(c1), .busy());
        end else begin : g_m1l
            assign div1_y = 32'd0; assign f_d1 = 1'b0; assign c1 = 1'b0;
            ot_hdc_delay__d4g_pgslice #(.W(T1W), .D(MLAT)) u_t1 (.clk(clk_stage[1]), .rst_n(rst_n), .d({p_b, p_c, p_d, p_o, p_par}), .q(t1));
            wire [MLAT:0] vl;
            ot_hdc_vline__d4g_pgslice #(.D(MLAT)) u_v1 (.clk(clk_stage[1]), .rst_n(rst_n), .v(p_v), .vd(vl));
            assign v1 = vl[MLAT];
        end
    endgenerate
    wire [31:0] m_b = t1[T1W-1 -: 32], m_c = t1[T1W-33 -: 32], m_d = t1[T1W-65 -: 32];
    wire [AW-1:0] m_oa = t1[AW:1];
    wire        m_par1 = t1[0];
    wire [31:0] P = (cm_m1 == M1_DIVB || cm_m1 == M1_DIVIMM) ? div1_y :
                    (cm_m1 == M1_AB || cm_m1 == M1_AA || cm_m1 == M1_AIMM) ? mul1_y : byp1;
    // ---- M2 and Q -----------------------------------------------------------------------------------------
    wire [31:0] m2_y, q_y, m2_byp;
    wire f_m2, f_q;
    ot_hdc_qmul_lat__d4g_pgslice #(MLAT) u_m2 (clk_stage[2], rst_n, v1 && cm_m2 != M2_BYP, P, (cm_m2 == M2_C) ? m_c : cm_imm1, m2_y, f_m2);
    wire qneg = (cm_qm == QM_NEG) || (cm_qm == QM_ALT_NP && !m_par1) || (cm_qm == QM_ALT_PN && m_par1);
    ot_hdc_qmul_lat__d4g_pgslice #(MLAT) u_q (clk_stage[2], rst_n, v1 && cm_qm != QM_OFF, m_c, {m_d[31] ^ qneg, m_d[30:0]}, q_y, f_q);
    wire [31:0] a2_b, a2_c, a2_d;
    wire [AW-1:0] a2_o;
    wire [1:0]  a2_m2;
    ot_hdc_delay__d4g_pgslice #(.W(32 * 4 + AW + 2), .D(MLAT)) u_d2 (.clk(clk_stage[2]), .rst_n(rst_n),
        .d({P, m_b, m_c, m_d, m_oa, cm_m2}), .q({m2_byp, a2_b, a2_c, a2_d, a2_o, a2_m2}));
    wire [MLAT:0] v2l;
    ot_hdc_vline__d4g_pgslice #(.D(MLAT)) u_v2 (.clk(clk_stage[2]), .rst_n(rst_n), .v(v1), .vd(v2l));
    wire v2 = v2l[MLAT];
    wire [31:0] P2 = (a2_m2 == M2_BYP) ? m2_byp : m2_y;
    // ---- AD ------------------------------------------------------------------------------------------------
    reg [31:0] ad_y;
    always @(*) begin
        case (ca_ad)
            AD_Q:    ad_y = q_y;
            AD_C:    ad_y = a2_c;
            AD_NEGB: ad_y = {~a2_b[31], a2_b[30:0]};
            AD_IMM:  ad_y = ca_imm2;
            default: ad_y = a2_d;
        endcase
    end
    wire [31:0] add_y, add_byp;
    wire f_ad;
    ot_hdc_qadd_lat__d4g_pgslice #(.KEEP(K), .LAT(ALAT)) u_ad (clk_stage[3], rst_n, v2 && ca_ad != AD_BYP, P2, ad_y, add_y, f_ad);
    wire [31:0] r_b, r_c;
    wire [AW-1:0] r_o;
    wire [2:0]  r_ad;
    ot_hdc_delay__d4g_pgslice #(.W(32 * 3 + AW + 3), .D(ALAT)) u_d3 (.clk(clk_stage[3]), .rst_n(rst_n),
        .d({P2, a2_b, a2_c, a2_o, ca_ad}), .q({add_byp, r_b, r_c, r_o, r_ad}));
    wire [ALAT:0] v3l;
    ot_hdc_vline__d4g_pgslice #(.D(ALAT)) u_v3 (.clk(clk_stage[3]), .rst_n(rst_n), .v(v2), .vd(v3l));
    wire v3 = v3l[ALAT];
    wire [31:0] R = (r_ad == AD_BYP) ? add_byp : add_y;
    // ---- S --------------------------------------------------------------------------------------------------
    localparam integer T4W = 32 * 3 + AW;                 // R, B, C', O
    wire [T4W-1:0] t4;
    wire           v4, c4;
    wire [31:0]    S;
    wire           f_sfu;
