            wire [31:0] y_exp, den, num_d, y_div;
            wire f_e, f_den, f_div;
            wire [D_EXP:0] ve;
            wire [D_EXP:0] vs;                 // a sigmoid-chain element, along the exp
            ot_hdc_vline__d4g_pgslice #(.D(D_EXP)) u_ve (.clk(clk_stage[4]), .rst_n(rst_n), .v(v3 && (is_exp || is_sig)), .vd(ve));
            ot_hdc_vline__d4g_pgslice #(.D(D_EXP)) u_vs (.clk(clk_stage[4]), .rst_n(rst_n), .v(v3 && is_sig), .vd(vs));
            ot_hdc_v41x_exp__d4g_pgslice #(.LM(MLAT), .LA(ALAT)) u_exp (.clk(clk_stage[4]), .rst_n(rst_n), .v(v3 && (is_exp || is_sig)),
