            wire [31:0] num_in = silu_in ? R : 32'h3F800000;
            ot_hdc_delay__d4g_pgslice #(.W(32), .D(D_EXP + ALAT)) u_num (.clk(clk_stage[4]), .rst_n(rst_n), .d(num_in), .q(num_d));
            wire [ALAT:0] vdn;
            ot_hdc_vline__d4g_pgslice #(.D(ALAT)) u_vdn (.clk(clk_stage[4]), .rst_n(rst_n), .v(vs[D_EXP]), .vd(vdn));
            ot_hdc_v41x_fdiv__d4g_pgslice u_div (.clk(clk_stage[4]), .rst_n(rst_n), .v(vdn[ALAT]), .a(num_d), .b(den), .y(y_div), .vo(),
