                          is_sig, is_exp, ci_sfu == SFU_NONE};
            if (FULL != 0) begin : g_full
                ot_hbm_su_static_ins__d4g_pgslice #(.W(T4W), .K(7),
                    .DEPTHS({H_EG, H_SP, H_SQRT, H_RSQ, H_SIG, H_EXP, 16'd0}), .DMAX(D_SP)) u_l4 (
                    .clk(clk_insert), .rst_n(rst_n), .v(v3), .sel(sel), .d({R, r_b, r_c, r_o}), .vo(v4), .q(t4), .coll(c4), .busy());
