    wire [31:0] e_b;
    wire [AW-1:0] e_o;
    wire [2:0]  e_e1;
    ot_hdc_delay__d4g_pgslice #(.W(32 * 2 + AW + 3), .D(MLAT)) u_d5 (.clk(clk_stage[5]), .rst_n(rst_n), .d({S, s_b, s_o, cs_e1}),
                                                   .q({e1_byp, e_b, e_o, e_e1}));
    wire [MLAT:0] v5l;
    ot_hdc_vline__d4g_pgslice #(.D(MLAT)) u_v5 (.clk(clk_stage[5]), .rst_n(rst_n), .v(v4), .vd(v5l));
    wire v5 = v5l[MLAT];
    wire [31:0] T = (e_e1 == E1_MULC || e_e1 == E1_MULIMM) ? e1m : (e_e1 == E1_ADDC || e_e1 == E1_ADDIMM) ? e1a :
                    e1_byp;
