    wire [AW-1:0] u_o;
    wire [1:0]  u_e2;
    ot_hdc_delay__d4g_pgslice #(.W(32 + AW + 2), .D(MLAT)) u_d6 (.clk(clk_stage[6]), .rst_n(rst_n), .d({T, e_o, ce_e2}),
                                               .q({e2_byp, u_o, u_e2}));
    wire [MLAT:0] v6l;
    ot_hdc_vline__d4g_pgslice #(.D(MLAT)) u_v6 (.clk(clk_stage[6]), .rst_n(rst_n), .v(v5), .vd(v6l));
    wire v6 = v6l[MLAT];
    wire [31:0] U = (u_e2 == E2_BYP) ? e2_byp : e2m;
