    reg r_vm_we, r_kv_we, r_ro_v, r_fault, r_coll; reg [AW-1:0] r_vm_waddr, r_kv_waddr; reg [31:0] r_vm_wdata, r_kv_wdata, r_ro_x;
    always @(posedge c7 or negedge rst_i) if (!rst_i) {r_vm_we, r_kv_we, r_ro_v, r_fault, r_coll} <= 5'd0;
