// Scoped source: rtl/hbm_accel/generic/adapters/static_su/arithmetic/ot_hbm_su_static_side.sv
`timescale 1ns/1ps
// ADDITIVE clock-only partition of original SIDE71b52f3016e76f1ef9ed3ca81333a73a0866b071dd4fa1c9f5727c49701c550b.
// Generated by tools/hbm_static/generate_static_side.py. No original file edits.
// clk[0] RSQRT8521;[1]SQRT3814;[2]SPexp10813;[3]SPpoly10794;
// [4]SPfinish9139;[5]EGATE13902 register sinks before optimization.
// All roots related1:1 phase0. No added input/output register or function edge.
// MLAT3/ALAT3 arithmetic is PHYSICALLY UNQUALIFIED at production833ps.
// MUT1 changes actual result mux function;MUT2 changes actual Engram sign.
module ot_hbm_su_static_side__d4g_pgslice #(parameter integer MUT=0) (
    input wire [5:0] clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [2:0]  fn,          // the S code at the S input
    input  wire [31:0] x,
    input  wire [2:0]  fn_out,      // the S code at the S output
    output wire [31:0] y,
    output wire        fault
);
    localparam integer MLAT=3, ALAT=3;
    wire [2:0] output_fn=fn_out ^ (MUT==1 ? 3'd1:3'd0);
    localparam [2:0] SFU_RSQRT = 2, SFU_SQRT = 3, SFU_SPSQRT = 6, SFU_EGATE = 7;
    localparam integer D_EXP = 7 * MLAT + 8 * ALAT + 4;    // ot_hdc_v41x_exp__d4g_pgslice DEPTH: 49 at 3 / 3
    localparam integer KS = (MLAT != 3 || ALAT != 3) ? 1 : 0;
    wire [31:0] y_rsq, y_sq, y_sp, y_eg;
    wire f_rsq, f_sq, f_sp, f_eg1, f_eg2, f_eg3, f_eg4;
    ot_hdc_v41x_rsqrt__d4g_pgslice #(.LM(MLAT), .LA(ALAT)) u_rsq (.clk(clk[0]), .rst_n(rst_n), .v(v && fn == SFU_RSQRT), .x(x), .y(y_rsq), .vo(),
                             .fault(f_rsq));
    ot_hdc_fsqrt__d4g_pgslice u_sq (.clk(clk[1]), .rst_n(rst_n), .v(v && fn == SFU_SQRT), .a(x), .y(y_sq), .vo(), .fault(f_sq));
    ot_hbm_su_static_side_softplus__d4g_pgslice #(.LM(MLAT), .LA(ALAT)) u_sp (.clk(clk[4:2]), .rst_n(rst_n), .v(v && fn == SFU_SPSQRT), .x(x), .sp(), .r(y_sp),
                               .vo(), .fault(f_sp));
    // Engram gate
    reg  [31:0] eg_m;
    reg         eg_v;
    reg  [31:0] eg_sgn;                 // the sign, along the square root (31)
    wire [31:0] absr = {1'b0, x[30:0]};
    wire        eg_le;                                  // absr <= 1e-6 (0x358637BD)
    ot_hdc_kge__d4g_pgslice #(.W(32), .K(KS)) u_egc (.a(32'h358637BD), .b(absr), .ge(eg_le));
    wire        eg_gt = !eg_le;
    always @(posedge clk[5] or negedge rst_n) begin
        if (!rst_n) eg_v <= 1'b0; else eg_v <= v && fn == SFU_EGATE;
    end
    always @(posedge clk[5]) begin
        eg_m <= eg_gt ? absr : 32'h358637BD;                           // max(|x|, 1e-6)
        eg_sgn <= {eg_sgn[30:0], x[31] && (x[30:0] != 31'd0)};
    end
    wire [31:0] eg_r;
    wire        eg_rv;
    ot_hdc_fsqrt__d4g_pgslice u_egs (.clk(clk[5]), .rst_n(rst_n), .v(eg_v), .a(eg_m), .y(eg_r), .vo(eg_rv), .fault(f_eg1));
    reg  [31:0] eg_s;
    reg         eg_sv;
    always @(posedge clk[5] or negedge rst_n) begin
        if (!rst_n) eg_sv <= 1'b0; else eg_sv <= eg_rv;
    end
    always @(posedge clk[5]) eg_s <= {eg_r[31] ^ eg_sgn[31] ^ (MUT==2), eg_r[30:0]};
    // sigmoid(eg_s) = 1 / (exp(-eg_s) + 1)
    wire [31:0] e_y, den;
    wire [D_EXP:0] ve;
    ot_hdc_vline__d4g_pgslice #(.D(D_EXP)) u_ve (.clk(clk[5]), .rst_n(rst_n), .v(eg_sv), .vd(ve));
    ot_hdc_v41x_exp__d4g_pgslice #(.LM(MLAT), .LA(ALAT)) u_exp (.clk(clk[5]), .rst_n(rst_n), .v(eg_sv), .x({~eg_s[31], eg_s[30:0]}), .y(e_y), .vo(),
                           .fault(f_eg2));
    ot_hdc_qadd_lat__d4g_pgslice #(.KEEP(KS), .LAT(ALAT)) u_den (clk[5], rst_n, ve[D_EXP], e_y, 32'h3F800000, den, f_eg3);
    wire [ALAT:0] vd;
    ot_hdc_vline__d4g_pgslice #(.D(ALAT)) u_vd (.clk(clk[5]), .rst_n(rst_n), .v(ve[D_EXP]), .vd(vd));
    ot_hdc_v41x_fdiv__d4g_pgslice u_div (.clk(clk[5]), .rst_n(rst_n), .v(vd[ALAT]), .a(32'h3F800000), .b(den), .y(y_eg), .vo(),
                            .fault(f_eg4));
    assign y = (output_fn == SFU_RSQRT) ? y_rsq : (output_fn == SFU_SQRT) ? y_sq : (output_fn == SFU_SPSQRT) ? y_sp : y_eg;
    assign fault = f_rsq | f_sq | f_sp | f_eg1 | f_eg2 | f_eg3 | f_eg4;
endmodule


module ot_hbm_su_static_side_softplus__d4g_pgslice #(
    parameter integer LM = 3,                   // multiplier latency (ot_hdc_qmul_lat__d4g_pgslice)
    parameter integer LA = 3                    // add latency (ot_hdc_qadd_lat__d4g_pgslice: 3, or 4 input cut)
) (
    input wire [2:0] clk,
    input  wire        rst_n,
    input  wire        v,
    input  wire [31:0] x,
    output wire [31:0] sp,
    output wire [31:0] r,
    output wire        vo,
    output wire        fault
);
    localparam integer T_EXP  = 7 * LM + 8 * LA + 4;   // ot_hdc_v41x_exp__d4g_pgslice DEPTH
    localparam integer T_DEN  = T_EXP + LA;
    localparam integer T_U    = T_DEN + 19;
    localparam integer T_U2   = T_U + LM;
    localparam integer T_P    = T_U2 + 8 * (LM + LA);
    localparam integer T_UP   = T_P + LM;
    localparam integer T_L    = T_UP + LM;
    localparam integer T_SP   = T_L + LA;
    localparam integer DEPTH  = T_SP + 31;       // 162 (LM 3), 180 (LM 4)
    localparam [32*9-1:0] C = {32'h3D70F0F1, 32'h3D888889, 32'h3D9D89D9, 32'h3DBA2E8C, 32'h3DE38E39,
                               32'h3E124925, 32'h3E4CCCCD, 32'h3EAAAAAB, 32'h3F800000};  // 1/17 .. 1/1
    function automatic [31:0] coef(input integer i);
        coef = C[32*(8-i) +: 32];
    endfunction

    wire [DEPTH:0] vd;
    ot_hdc_vline__d4g_pgslice #(.D(DEPTH)) u_v (.clk(clk[0]), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];

    wire [31:0] t, den, t_d, u, u2, lp, l;
    wire f_exp, f_den, f_div, f_u2, f_up, f_l, f_sp, f_sq;
    ot_hdc_v41x_exp__d4g_pgslice #(.LM(LM), .LA(LA)) u_exp (.clk(clk[0]), .rst_n(rst_n), .v(v), .x({1'b1, x[30:0]}), .y(t), .vo(), .fault(f_exp));
    ot_hdc_qadd_lat__d4g_pgslice #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_den (clk[0], rst_n, vd[T_EXP], t, 32'h40000000, den, f_den);
    ot_hdc_delay__d4g_pgslice #(.W(32), .D(LA)) d_t (clk[0], rst_n, t, t_d);
    ot_hdc_v41x_fdiv__d4g_pgslice u_div (.clk(clk[0]), .rst_n(rst_n), .v(vd[T_DEN]), .a(t_d), .b(den), .y(u), .vo(), .fault(f_div));
    ot_hdc_qmul_lat__d4g_pgslice #(LM) m_u2 (clk[0], rst_n, vd[T_U], u, u, u2, f_u2);

    wire [31:0] u2d [0:7];
    wire [31:0] pm  [1:8];
    wire [31:0] pa  [0:8];
    wire [16:1] hf;
    assign u2d[0] = u2;
    assign pa[0] = coef(0);
    genvar k;
    generate
        for (k = 1; k <= 8; k = k + 1) begin : g_h
            if (k < 8) begin : g_d
                ot_hdc_delay__d4g_pgslice #(.W(32), .D(LM + LA)) d_u2 (clk[1], rst_n, u2d[k-1], u2d[k]);
            end
            ot_hdc_qmul_lat__d4g_pgslice #(LM) u_m (clk[1], rst_n, vd[T_U2 + (LM + LA)*(k-1)], pa[k-1], u2d[k-1], pm[k], hf[2*k-1]);
            ot_hdc_qadd_lat__d4g_pgslice #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) u_a (clk[1], rst_n, vd[T_U2 + (LM + LA)*(k-1) + LM], pm[k], coef(k), pa[k], hf[2*k]);
        end
    endgenerate

    wire [31:0] u_d;
    ot_hdc_delay__d4g_pgslice #(.W(32), .D(T_P - T_U)) d_u (clk[1], rst_n, u, u_d);
    ot_hdc_qmul_lat__d4g_pgslice #(LM) m_up (clk[1], rst_n, vd[T_P], u_d, pa[8], lp, f_up);
    ot_hdc_qmul_lat__d4g_pgslice #(LM) m_l  (clk[1], rst_n, vd[T_UP], lp, 32'h40000000, l, f_l);

    reg  [31:0] mx;
    wire [31:0] mx_d, spv;
    wire x_nan = (x[30:23] == 8'hFF) && (x[22:0] != 23'd0);
    always @(posedge clk[2]) mx <= (x[31] && !x_nan) ? 32'd0 : x;
    ot_hdc_delay__d4g_pgslice #(.W(32), .D(T_L - 1)) d_mx (clk[2], rst_n, mx, mx_d);
    ot_hdc_qadd_lat__d4g_pgslice #(.KEEP((LM != 3 || LA != 3) ? 1 : 0), .LAT(LA)) a_sp (clk[2], rst_n, vd[T_L], mx_d, l, spv, f_sp);

    ot_hdc_fsqrt__d4g_pgslice u_sq (.clk(clk[2]), .rst_n(rst_n), .v(vd[T_SP]), .a(spv), .y(r), .vo(), .fault(f_sq));
    ot_hdc_delay__d4g_pgslice #(.W(32), .D(DEPTH - T_SP)) d_sp (clk[2], rst_n, spv, sp);

    wire f_sp_d;
    ot_hdc_delay__d4g_pgslice #(.W(1), .D(DEPTH - T_SP), .RESET(1)) d_fsp (clk[2], rst_n, f_sp, f_sp_d);
    assign fault = f_sp_d | f_sq | f_exp | f_den | f_div | f_u2 | (|hf) | f_up | f_l;
endmodule

// Scoped source: rtl/hbm_accel/generic/adapters/static_su/data_store/ot_hbm_su_static_data_store.sv
`timescale 1ns/1ps
`default_nettype none
// One independently hardened bank, six read replicas, one canonical write.
// The caller supplies compiler-assigned bank slots. No queues/arbitration or
// producer handshakes exist. All replicas see identical writes, including
// masked-word semantics inside the REAL provider SRAM. Read address conflicts
// between consumers must be resolved by the compiler before this boundary.
module ot_hbm_su_static_replicated_bank__d4g_pgslice #(
 parameter integer READERS=6,RB=9,MUT_COHERENCE=0
)(
 input wire clk, // word-select flops stay on the boundary register root
 input wire[READERS-1:0]clk_macro,
 input wire[READERS-1:0]read_v,
 input wire[READERS*RB-1:0]read_addr,
 output wire[READERS*32-1:0]read_data,
 input wire write_v,input wire[RB-1:0]write_addr,input wire[31:0]write_data
);
 // Exact RB9 provider geometry of ot_hgi_su_lbank:512 words in64
 // active rows of the actual128x256 SRAM. Word mask and read-before-write
 // semantics are unchanged. Only the SRAM pin gets its own raw clock entry.
 initial if(RB!=9)$fatal(1,"static replicated bank requires RB9 actual128x256 provider");
 for(genvar r=0;r<READERS;r=r+1)begin:g_read
  reg[2:0]ks;
  always @(posedge clk)if(read_v[r])ks<=read_addr[r*RB+:3];
  wire[255:0]raw;
  wire[255:0]mask={224'd0,32'hffffffff} << {write_addr[2:0],5'd0};
  ot_sram_1r1w_128x256_m1_r2c2 u_m(
   .clk(clk_macro[r]),.r_ce_in(read_v[r]),.r_addr_in({1'b0,read_addr[r*RB+3+:6]}),.rd_out(raw),
   .w_ce_in(write_v&&!(MUT_COHERENCE!=0&&r==READERS-1)),.w_addr_in({1'b0,write_addr[8:3]}),
   .wd_in({8{write_data}}),.w_mask_in(mask),.rr_en(2'b00),.rr_addr(14'd0),.cr_en(2'b00),.cr_sel(16'd0));
  assign read_data[r*32+:32]=raw[{ks,5'd0}+:32];
 end
endmodule

// Full aggregate N512/LWB18 data capacity, partitioned into four quarters.
// Global word address decomposition preserves FOUR frames, each quartered:
// frame=a[17:16], quadrant=a[15:14], bank=a[6:0], row={a[17:16],a[13:7]}.
// Each q contains128 bank leaves; each leaf has its own compensated clock pin.
// Payload wiring is explicit and there is no memory model in this parent.
module ot_hbm_su_static_data_store__d4g_pgslice #(
 parameter integer QUARTERS=4,BANKS_PER_QUARTER=128,READERS=6,RB=9,MUT_COHERENCE=0
)(
 input wire[QUARTERS*BANKS_PER_QUARTER-1:0]clk_bank,
 input wire[QUARTERS*BANKS_PER_QUARTER*READERS-1:0]clk_macro,
 input wire[QUARTERS*BANKS_PER_QUARTER*READERS-1:0]read_v,
 input wire[QUARTERS*BANKS_PER_QUARTER*READERS*RB-1:0]read_addr,
 output wire[QUARTERS*BANKS_PER_QUARTER*READERS*32-1:0]read_data,
 input wire[QUARTERS*BANKS_PER_QUARTER-1:0]write_v,
 input wire[QUARTERS*BANKS_PER_QUARTER*RB-1:0]write_addr,
 input wire[QUARTERS*BANKS_PER_QUARTER*32-1:0]write_data
);
 for(genvar q=0;q<QUARTERS;q=q+1)begin:g_q
  for(genvar b=0;b<BANKS_PER_QUARTER;b=b+1)begin:g_bank
   localparam I=q*BANKS_PER_QUARTER+b;
   ot_hbm_su_static_replicated_bank__d4g_pgslice #(.READERS(READERS),.RB(RB),.MUT_COHERENCE(MUT_COHERENCE))u_bank(
    .clk(clk_bank[I]),.clk_macro(clk_macro[I*READERS+:READERS]),.read_v(read_v[I*READERS+:READERS]),
    .read_addr(read_addr[I*READERS*RB+:READERS*RB]),.read_data(read_data[I*READERS*32+:READERS*32]),
    .write_v(write_v[I]),.write_addr(write_addr[I*RB+:RB]),.write_data(write_data[I*32+:32]));
  end
 end
endmodule
`default_nettype wire

// Scoped source: rtl/hbm_accel/generic/adapters/static_su/data_store/ot_hbm_su_static_pinned_bank.sv
`timescale 1ns/1ps
`default_nettype none
// Physical leaf boundary: sample at n, actual SRAM read/write at n+1,
// registered data/return pins at n+2. Payload is not reset. The compiler
// prices both read edges and the +1 write commit; there is no retry path.
module ot_hbm_su_static_pinned_bank__d4g_pgslice #(
 parameter integer READERS=6,RB=9,MUT_COHERENCE=0,MUT_RETURN=0,
 // RD_ROOT 1 (H-SU 10-15, bank clock7 r7): the read-side output registers (read_data, read_return) take their own
 // related root clk_rd entering at the read face, so no register-clock net crosses the SRAM columns
 parameter integer RD_ROOT=0,
 // WS_ROOT (H-SU 10-15, bank r10b): clock of the 18 word-select flops (ks), which sit at each SRAM column's pin edge.
 // 0 = clk (r9: the clk tree then spans every macro column, R 196.6 / spread 74.7 -> native capture 224 > 190);
 // 1 = clk_rd (r10 gate: clk_rd insertion 308.7 / spread 57.1, the E-face read root then spans the columns);
 // 2 = clk_ws, the interior root: ks plus (PIN_RST) the mid-tile return-valid stage r_macro, so clk stays at the
 //     W-face pin registers and clk_rd at the E-face ones (r10b gate with r_macro on clk / rst_r on clk_rd: clk spread
 //     42.8, clk_rd 174.5 / spread 64.2 -- one stray sink each). clk_ws reaches no pin.
 parameter integer WS_ROOT=0,
 // PIN_RST 1 (bank r10): rst_n is a synchronous data input registered at the W face like every other input
 // (r_pin/w_pin gate on it directly, so the first command after release is taken on the same edge as before); the
 // internal return-valid stage gates on the registered copy rst_w; r_return needs no reset of its own (its only source
 // r_macro is cleared). Requires >= 3 clock edges in reset;
 // reset is entered from idle (a read sampled before the asserting edge may still return within 2 edges).
 parameter integer PIN_RST=0,
 parameter integer MUT_RESET=0 // bench mutant: a write issued during reset lands (reset gate dropped on w_pin)
)(
 input wire clk,rst_n,
 input wire clk_rd, // same serial clock as clk (related root); used only when RD_ROOT=1
 input wire clk_ws, // same serial clock as clk (related root); used only when WS_ROOT=2
 input wire[READERS-1:0]clk_macro, // six distinct physical roots; phase-compensated to clk
 input wire[READERS-1:0]read_v,input wire[READERS*RB-1:0]read_addr,
 output reg[READERS*32-1:0]read_data,output wire[READERS-1:0]read_return,
 input wire write_v,input wire[RB-1:0]write_addr,input wire[31:0]write_data
);
 reg[READERS-1:0]r_pin,r_macro,r_return,r_late;
 reg[READERS*RB-1:0]a_pin;
 reg w_pin;reg[RB-1:0]wa_pin;reg[31:0]wd_pin;
 wire[READERS*32-1:0]raw_data;
 wire c_rd=(RD_ROOT!=0)?clk_rd:clk;
 always @(posedge clk)begin
  a_pin<=read_addr;wa_pin<=write_addr;wd_pin<=write_data;
 end
 always @(posedge c_rd)read_data<=raw_data;
 wire c_ws=(WS_ROOT==2)?clk_ws:(WS_ROOT==1)?c_rd:clk;
 if(PIN_RST!=0)begin:g_pin_rst
  reg rst_w;
  always @(posedge clk)begin
   rst_w<=rst_n;
   r_pin<=read_v&{READERS{rst_n}};
   w_pin<=write_v&&(rst_n||MUT_RESET!=0);
  end
  always @(posedge c_ws)r_macro<=r_pin&{READERS{rst_w}};
  always @(posedge c_rd)begin
   r_return<=r_macro;
   r_late<=r_return;
  end
 end else begin:g_async_rst
  always @(posedge clk or negedge rst_n)begin
   if(!rst_n)begin r_pin<=0;r_macro<=0;w_pin<=0;end
   else begin r_pin<=read_v;r_macro<=r_pin;w_pin<=write_v;end
  end
  always @(posedge c_rd or negedge rst_n)begin
   if(!rst_n)begin r_return<=0;r_late<=0;end
   else begin r_return<=r_macro;r_late<=r_return;end
  end
 end
 assign read_return=MUT_RETURN!=0?r_late:r_return;
 ot_hbm_su_static_replicated_bank__d4g_pgslice #(.READERS(READERS),.RB(RB),.MUT_COHERENCE(MUT_COHERENCE))u_data(
  .clk(c_ws),.clk_macro(clk_macro),.read_v(r_pin),.read_addr(a_pin),.read_data(raw_data),
  .write_v(w_pin),.write_addr(wa_pin),.write_data(wd_pin));
endmodule
`default_nettype wire

// Scoped source: rtl/hbm_accel/generic/adapters/static_su/ot_hbm_su_static_vm_ports.sv
`timescale 1ns/1ps
`default_nettype none
// Static SU VM interface of one quarter: NPG independently placeable port groups, one per VM bank pair.
// ADOPTED floorplan T_band2__npg4_s5 (GLOBAL-FP-H, main 952c5933c; coordinator 09:35 PT 10-15): the 8-bank slice sits in
// the 1.8 mm VM band between SM rows 2/3, so EVERY quadrant incl. SW/SE uses 4 bank-pair groups (NPG 4,
// BANK_GROUP 32'h3322_1100 = {0,0,1,1,2,2,3,3}); the earlier 5-group SW/SE map (0x43322110, v15/D geometry) is
// superseded (with it the adopted plan's worst cut is 0.636 instead of 0.556). NPG/BANK_GROUP stay parameters so the
// die contract states the map; the logical buses below stay one port per quarter, only the pin/leaf plan and the
// clock root follow the group.
// Each bank leaf drives the SU (near) station of the LG tap of its bank (ot_hbm_vm_lg_static_bank__d4g_pgslice, READ_RETURN 10,
// WRITE_RETURN 7). No register stage is added: request pins go straight to the LG leaf's sampled local inputs, so
// the compiler latencies stay 10/7. No queues, credits, ready, arbitration or runtime rescheduling.
// The LG tap's read/write SELECTS are NOT driven here: one source, the VM calendar programme (compiler-scheduled,
// h_vm; coordinator decision 10-15 on main 517963b2f). The SU issues on the calendar's slots; a request off the
// calendar is not sampled by the leaf, so its return never arrives and the return check latches FAULT.
// Checks only (never stall, never replay):
//   * a request must address this quarter's slice (SID == QID, no mirror) and its own bank (F2 per-quarter spread);
//   * every read must return exactly READ_RETURN edges later, every write must be done exactly WRITE_RETURN edges
//     later; a missing or unsolicited return latches FAULT.
// MUT=1 (bench must fail): the leaf forgets the per-quarter spread and sends the logical SID-major slice bits.
module ot_hbm_su_static_vm_bank_leaf__d4g_pgslice #(parameter integer QID=0,B=0,READ_RETURN=10,WRITE_RETURN=7,MUT=0)(
 input wire clk,rst_n,
 input wire [16:0] su_rq,                // {v,sector16}
 input wire [280:0] su_wq,               // {v,sector16,data256,mask8}
 output wire [256:0] su_rr,              // {v,data256} at issue + READ_RETURN
 output wire su_w_done,
 output wire [16:0] lg_rq,output wire [280:0] lg_wq,
 input wire [256:0] lg_rr,input wire lg_w_done,
 output reg fault
);
 reg rcal[0:READ_RETURN];   // rcal[k] (as seen before an edge) = request sampled k edges earlier
 reg wcal[0:WRITE_RETURN];
 function automatic ok(input [15:0] s);
  ok=!s[15]&&s[14:13]==2'(QID)&&s[2:0]==3'(B);
 endfunction
 wire [15:0] sec=su_rq[15:0];
 assign lg_rq={su_rq[16],MUT!=0?{sec[15],2'(QID^1),sec[12:0]}:sec};
 assign lg_wq=su_wq;
 assign su_rr=lg_rr;
 assign su_w_done=lg_w_done;
 integer i;
 always @(posedge clk or negedge rst_n)
  if(!rst_n)begin
   fault<=0;for(i=0;i<=READ_RETURN;i=i+1)rcal[i]<=0;for(i=0;i<=WRITE_RETURN;i=i+1)wcal[i]<=0;
  end else begin
