// Scoped source: rtl/hbm_accel/generic/adapters/static_su/programme/multirate_bridge.sv
`timescale 1ns/1ps
// Candidate boundary only. Requires exact phase-zero 3:4 common epoch.
// Clock compensation and phase/reset establishment are integration obligations.
// Every transfer uses compiler-reserved slots; faults never alter issue timing.
// HBM-BANKLAT-SU 2026-10-19: READ_RETURN / WRITE_RETURN = the stream LG round trip (LG samples the request at stream
// edge j+1, presents the read answer at j+1+READ_RETURN / the write done at j+1+WRITE_RETURN; default 10/7 = the
// zero-lane non-pin bank). The serial presentation edge is derived, not a free constant:
//   SRD = ceil((3*READ_RETURN+18)/4), SWD = ceil((3*WRITE_RETURN+18)/4)   (12 / 10 at the defaults)
// i.e. the first serial edge at least 6 quanta after the latest stream capture 3(j+RT+2) <= 4n+3RT+12; the next
// same-slot capture (source n+4) is >= 4n+3RT+26, so the slot-overwrite guard stays >= 5 quanta for every RT.
// Every register width/index reduces to the 10/7 structure at the defaults (bit-identical netlist).
module ot_hbm_su_multirate_bridge__d4g_pgslice #(
 parameter integer RQ_BITS=17,WQ_BITS=281,RR_BITS=257,
 parameter integer MUT_SLOT=0,
 parameter integer READ_RETURN=10,
 parameter integer WRITE_RETURN=7
)(input wire serial_clk,stream_clk,rst_n,
 input wire [RQ_BITS-1:0] serial_rq,input wire [WQ_BITS-1:0] serial_wq,
 output reg [RR_BITS-1:0] serial_rr,output reg serial_done,
 output reg [RQ_BITS-1:0] stream_rq,output reg [WQ_BITS-1:0] stream_wq,
 input wire [RR_BITS-1:0] stream_rr,input wire stream_done,
 output reg fault);
 // These are explicit register banks, not an asynchronous FIFO or a behavioral
 // memory substitution. Four slots prevent cross-clock read/write overlap.
 reg [RQ_BITS-1:0] rq_slot[0:3];reg [WQ_BITS-1:0] wq_slot[0:3];
 reg [RR_BITS-1:0] rr_slot[0:3];reg done_slot[0:3];
 reg [1:0] serial_slot;
 localparam integer SRD=(3*READ_RETURN+18+3)/4, SWD=(3*WRITE_RETURN+18+3)/4;
 localparam integer RP=READ_RETURN+2, WP=WRITE_RETURN+2;          // stream capture edge after the register event
 localparam integer WW=$clog2(SRD+1)>$clog2(SWD+1)?$clog2(SRD+1):$clog2(SWD+1);
 initial if(READ_RETURN<10||WRITE_RETURN<7||WRITE_RETURN>READ_RETURN)$fatal(1,"bridge: LG round trip below the 10/7 zero-lane contract (or write > read)");
 reg [WW-1:0] serial_warm;
 reg [3:0] phase;
 reg [4:0] stream_warm;
 reg [RP-1:0] active_pipe,read_pipe;
 reg [WP-1:0] write_pipe;
 // Request-register event j: j mod4=2 -> n=3floor(j/4),
 // mod4=3 -> n=3floor(j/4)+1, mod4=0 -> n=3floor(j/4)-1.
 // j=0 is suppressed at epoch startup. Low four j bits identify n mod4.
 function automatic [1:0] slot_for_phase(input [3:0] p);
  reg [3:0] n;
  begin
   n=3*{2'b0,p[3:2]};
   if(p[1:0]==3)n=n+1;
   if(p[1:0]==0)n=n-1;
   slot_for_phase=n[1:0];
  end
 endfunction
 wire active=phase[1:0]!=1 && stream_warm>=2;
 wire [1:0] launch_slot=slot_for_phase(phase)+2'(MUT_SLOT);
 wire [1:0] read_slot=slot_for_phase(phase-4'(RP));
 wire [1:0] done_slot_index=slot_for_phase(phase-4'(WP));
 integer k;
 always @(posedge serial_clk or negedge rst_n)begin
  if(!rst_n)begin
   serial_slot<=0;serial_warm<=0;serial_rr<=0;serial_done<=0;
   for(integer i=0;i<4;i=i+1)begin rq_slot[i]<=0;wq_slot[i]<=0;end
  end else begin
   rq_slot[serial_slot]<=serial_rq;wq_slot[serial_slot]<=serial_wq;
   // source n-SRD sits in slot (n-SRD) mod4 (SRD 12: the same slot); n-SWD in (n-SWD) mod4 (SWD 10: n+2).
   serial_rr <= serial_warm>=WW'(SRD) ? rr_slot[serial_slot-2'(SRD)] : '0;
   serial_done <= serial_warm>=WW'(SWD) ? done_slot[serial_slot-2'(SWD)] : 1'b0;
   serial_slot<=serial_slot+1'b1;
   if(serial_warm<WW'(SRD>SWD?SRD:SWD))serial_warm<=serial_warm+1'b1;
  end
 end
 always @(posedge stream_clk or negedge rst_n)begin
  if(!rst_n)begin
   phase<=0;stream_warm<=0;stream_rq<=0;stream_wq<=0;
   active_pipe<=0;read_pipe<=0;write_pipe<=0;fault<=0;
   for(integer i=0;i<4;i=i+1)begin rr_slot[i]<=0;done_slot[i]<=0;end
  end else begin
   phase<=phase+1'b1;if(stream_warm<16)stream_warm<=stream_warm+1'b1;
   stream_rq<=active ? rq_slot[launch_slot] : '0;
   stream_wq<=active ? wq_slot[launch_slot] : '0;
   active_pipe<={active_pipe[RP-2:0],active};
   read_pipe<={read_pipe[RP-2:0],active && rq_slot[launch_slot][RQ_BITS-1]};
   write_pipe<={write_pipe[WP-2:0],active && wq_slot[launch_slot][WQ_BITS-1]};
   // LG response is presented after issue+READ_RETURN; capture one full stream cycle
   // later, then hold this slot until its fixed serial n+SRD read.
   if(active_pipe[RP-1])rr_slot[read_slot]<=stream_rr;
   if(active_pipe[WP-1])done_slot[done_slot_index]<=stream_done;
   if(stream_rr[RR_BITS-1]!==read_pipe[RP-1] || stream_done!==write_pipe[WP-1])fault<=1;
  end
 end
endmodule

// Scoped source: rtl/hbm_accel/generic/adapters/static_su/top/ot_hbm_su_static_pgslice.sv
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------------
// Static SU port-group SLICE (H-ELEM-B 2026-10-15): the physical sub-block of quarter QID that sits at VM bank pair
// {2G, 2G+1} of slice QID (adopted floorplan T_band2__npg4_s5: blocks su_<q>0..3 in the VM band, NPG 4 everywhere).
// Contents: 32 arithmetic lanes (quarter-local ids 16G..16G+15 and 64+16G..64+16G+15), their 32 pinned store banks
// (lane i reads/writes only bank i), the two SU-station VM bank leaves ot_hbm_su_static_vm_bank_leaf__d4g_pgslice of banks 2G/2G+1
// (= port group G of ot_hbm_su_static_vm_ports__d4g_pgslice), and the local fill / drain datapaths. Global lane 0 (QID 0, G 0) carries
// the scalar SIDE pipe ot_hbm_su_static_side__d4g_pgslice.
// Locality rule (compiler, checked): VM port p (= VM bank p of the slice) fills and drains ONLY store groups p and p+8
// (8 banks each), which is exactly where the F2 per-quarter spread puts the words of a 128-word issue block (sector s ->
// VM bank s mod 8, store group s mod 16). So no store bank is ever reached from outside its slice.
// Timing (all fixed; edge = rising clk edge at which a command / pin value is sampled):
//   FILL  vmr_cmd[h] = {v, sector16, grp4, row9} at edge E: LG samples the request at E, returns data held E+10..E+11,
//         the slice registers it at E+11 (FILL_REG 1: one physical stage across the slice), bank pins sample E+12,
//         commit E+13 (readable by a bank read sampled at >= E+13).
//   DRAIN vmw_cmd[h] = {v, src, grp4, row9, sector16, mask8} at E: store drain replica sampled at E, data held E+2..E+3,
//         2:1 group select registered at E+3, LG samples the write at E+4, write done +7. src 1 (RF sector, port 0 of
//         slice 0 only) takes the quarter core's rf_dsec (core RF class-5 read issued at E-1, registered at E+3).
//   LANE  store reads sampled at n are consumed by the lane at n+3 (FETCH_EXTRA_EDGES 2); an RF-source stream (code 1)
//         takes rf_bword[p] (core register held n+2..n+3: core RF class-p read issued at n-1); the lane address must
//         equal rf_bcmd[p] (class-p command delayed one edge by the core).
//   RED   red_sel = {v, op3, osel, lane7} at E: if the lane is in this slice, its ro_x is registered at E (slice_x) and
//         must be live (ro_v) when the op takes an external operand.
// Checks latch FAULT (never stall): lane fault/collision, VM leaf spread/return checks, fill+lane write on one bank,
// command naming a group outside the port's pair, lane write / VM read outside its own bank and quarter, RF-source
// stream address != command, lane source code 2/3 (no constant ROM), RF drain on a port other than slice 0 port 0,
// reducer operand from a non-emitting lane, SIDE fault.
// MUT (bench, must FAIL): 1 fill registered one edge early; 2 drain group select flipped; 4 RF-broadcast select one
// edge early.
// ---------------------------------------------------------------------------------------------------------------------
module ot_hbm_su_static_pgslice__d4g_pgslice #(
 parameter integer QID=0,G=0,READ_RETURN=10,WRITE_RETURN=7,FETCH_EXTRA_EDGES=2,MLAT=3,ALAT=3,LEAF=0,MUT=0,MULTIRATE=0,
 // PIN_REG (owner rule 10-15 19:50): every lane is the pin-registered leaf ot_hbm_su_static_lane_pinreg__d4g_pgslice: its store /
 // RF-stream requests leave +2 edges and its writes / reducer operands +4 edges later (su_top_compile --pin-reg)
 parameter integer PIN_REG=0,
 // COLLPORT (H-NETLIST/suport 2026-10-16, default 0 = unchanged): the quarter's COLL joins through ot_hbm_su_static_cxport.
 //   INJECT  inj_rd/inj_addr (stream, from COLL, captured at A in a stream pin slot); serial edge n = ceil((3A+3)/4)
 //           (A mod 4 in {0,1,3}) drives bank READ PORT 5 (shared with DRAIN by the compiler calendar) of the store groups
 //           named by the 4 sectors (2 lanes x lo/hi): group g = a[6:3], this slice iff a[5:4]==G, h = a[3], hi = a[6],
 //           row a[15:7]; inj_q = the 32 banks' port-5 read_data (n+2), registered by the cxport at n+3.
 //           B39_NOOP (SW): a lane whose addr_lo[39]=1 is an IDX-staging read: no SU read.
 //   DELIVERY dw_v/dw_row/dw_d (serial, cxport registers at n): half hi writes banks 16hi..16hi+15 (word w -> bank
 //           16hi+w) at row; bank pins sample n+1, commit n+2. Write port priority fill > delivery > lane; any two in one
 //           edge latch FAULT.
 //   Checks (FAULT): inject and drain on one group in one edge; two sectors on one group with different rows.
 //   MUT (bench): 8 inject slot map off by one phase; 9 B39 no-op ignored; 10 delivery word order reversed.
 parameter integer COLLPORT=0,
 parameter integer B39_NOOP=(QID==0),
 // RF_LOCAL (H-SU 2026-10-16, d4c 2 mm locality rule; default 0 = unchanged): the quarter core's RF broadcast
 //   (rf_bword 128 + rf_bcmd 36 + rf_dsec 256) is registered ONCE more here, beside this bank group (clk_ctl), so the
 //   die route core -> slice ends in a local fixed-latency copy and every slice sees the same age. The compiler issues
 //   RF classes 0..3 and 5 one edge earlier (su_top_compile --rf-local 1): class p at n-2 for a lane request at n
 //   (core register held n+1..n+2, local copy held n+2..n+3, consumed n+3 as before); class 5 at E-2 for the drain at E
 //   (local rf_dsec held E+3). Lane / drain / reducer edges and the op calendar are unchanged; no stall, no dynamic path.
 parameter integer RF_LOCAL=0,
 // PG_RSYNC (HBM-SU3 2026-10-17; default 0 = unchanged): the two stream-domain VM bank leaves (pg_clk) no longer take
 //   the serial power-on reset rst_n as a raw asynchronous clear. rst_n is registered once on clk_ctl (g_pg_rsync.rc,
 //   serial source flop) and re-timed by two pg_clk flops (rs[0] -> rs[1]); rs[1] is the leaves' reset (assert and
 //   release on pg_clk edges, serial->stream crossing on a reviewed 1-bit synchroniser, as col_su r3). Serial and stream
 //   share one fixed-phase PLL lattice, so the release edge is deterministic: the first serial edge that samples
 //   rst_n=1, then the second following pg_clk edge. Datapath edges unchanged; only reset assert/release move.
 parameter integer PG_RSYNC=0
)(
