   .side_v(sv),.side_x(sx),.side_y(side_y));
  end else begin:g_plain
  ot_hbm_su_static_lane__d4g_pgslice #(.LN(7),.KIND(KIND),.MLAT(MLAT),.ALAT(ALAT),.LEAF(LEAF),.FETCH_EXTRA_EDGES(FETCH_EXTRA_EDGES)) u_lane(
   .clk_stage(clk_lane[n*8+:8]),.clk_insert(clk_insert[n*4+:4]),.rst_n(rst_lane_n[n]),.lane_id(11'(L)),
   .cx_srcs(c_srcs),.ld(c_ld),.ld_bank(c_ld_bank),.ld_c(terms),.emit(c_emit),.bank(c_bank),.o_v(c_o_v),.i_v(c_i_v),
   .no(c_no),.ni(c_ni),.ls(c_ls),.lvw(c_lvw),.vb(c_vb),.krow(c_krow),.obase(c_obase),.aibase(c_aibase),.aind(c_aind),
   .gsh(c_gsh),.cpair(c_cpair),.dst(c_dst),.srcs(c_srcs),.cx_arnd(c_cx_arnd),.cx_arelu(c_cx_arelu),.cx_amin(c_cx_amin),
   .cx_cclip(c_cx_cclip),.cx_imm3(c_cx_imm3),.cp_m1(c_cp_m1),.cp_imm1(c_cp_imm1),.cm_m1(c_cm_m1),.cm_m2(c_cm_m2),
   .cm_qm(c_cm_qm),.cm_imm1(c_cm_imm1),.ca_ad(c_ca_ad),.ca_imm2(c_ca_imm2),.ci_sfu(c_ci_sfu),.cs_sfu(c_cs_sfu),
   .cs_e1(c_cs_e1),.cs_imm2(c_cs_imm2),.ce_e2(c_ce_e2),.ce_imm1(c_ce_imm1),.co_rnd(c_co_rnd),.co_dst(c_co_dst),
   .vi_q(vi_q[n*32+:32]),.rd_q(rd_q[n*128+:128]),.vi_re(vi_re[n]),.vm_we(vm_we[n]),.kv_we(kv_we[n]),.ro_v(ro_v[n]),
   .fault(l_fault[n]),.coll(l_coll[n]),.vi_addr(vi_addr[n*24+:24]),.vm_waddr(vm_waddr[n*24+:24]),
   .kv_waddr(kv_waddr[n*24+:24]),.rd_addr(rd_addr[n*96+:96]),.rd_re(rd_re[n*4+:4]),.rd_src(rd_src[n*8+:8]),
   .vm_wdata(vm_wdata[n*32+:32]),.kv_wdata(kv_wdata[n*32+:32]),.ro_x(ro_x[n*32+:32]),
   .side_v(sv),.side_x(sx),.side_y(side_y));
  end
 end
 if(QID==0&&G==0)begin:g_side_pipe
  ot_hbm_su_static_side__d4g_pgslice u_side(.clk(clk_side),.rst_n(rst_n),.v(side_v),.fn(side_fn),.x(side_x),.fn_out(side_fn_out),
   .y(side_y),.fault(side_fault));
 end else begin:g_no_side
  // no FULL lane in this slice: the side result input of its SFU/LIGHT lanes is not used by the lane
  assign side_y=32'd0; assign side_fault=1'b0;
  assign side_v=1'b0; assign side_x=32'd0; assign side_fn=3'd0; assign side_fn_out=3'd0;
 end
 // ------------------------------------------------------------------ VM bank leaves (port group G = banks 2G, 2G+1)
 wire [2*17-1:0] su_rq; wire [2*281-1:0] su_wq; wire [2*257-1:0] su_rr; wire [1:0] su_w_done,leaf_fault,bridge_fault;
 wire [33:0] leaf_rq; wire [561:0] leaf_wq; wire [513:0] leaf_rr; wire [1:0] leaf_done;
 wire leaf_rst_n;
 if(PG_RSYNC)begin:g_pg_rsync
  reg rc; reg [1:0] rs;
  always @(posedge clk_ctl) rc <= rst_n;
  always @(posedge pg_clk) rs <= {rs[0], rc};
  assign leaf_rst_n = rs[1];
 end else begin:g_pg_rst_raw
  assign leaf_rst_n = rst_n;
 end
 for(genvar h=0;h<2;h=h+1)begin:g_leaf
  if(MULTIRATE)begin:g_multirate
   ot_hbm_su_multirate_bridge__d4g_pgslice #(.READ_RETURN(READ_RETURN),.WRITE_RETURN(WRITE_RETURN)) u_bridge(
    .serial_clk(clk_ctl),.stream_clk(pg_clk),.rst_n(bridge_rst_n),
    .serial_rq(su_rq[h*17+:17]),.serial_wq(su_wq[h*281+:281]),
    .serial_rr(su_rr[h*257+:257]),.serial_done(su_w_done[h]),
    .stream_rq(leaf_rq[h*17+:17]),.stream_wq(leaf_wq[h*281+:281]),
    .stream_rr(leaf_rr[h*257+:257]),.stream_done(leaf_done[h]),.fault(bridge_fault[h]));
  end else begin:g_same_clock
   assign leaf_rq[h*17+:17]=su_rq[h*17+:17];
   assign leaf_wq[h*281+:281]=su_wq[h*281+:281];
   assign su_rr[h*257+:257]=leaf_rr[h*257+:257];
   assign su_w_done[h]=leaf_done[h];
   assign bridge_fault[h]=1'b0;
  end
  ot_hbm_su_static_vm_bank_leaf__d4g_pgslice #(.QID(QID),.B(2*G+h),.READ_RETURN(READ_RETURN),.WRITE_RETURN(WRITE_RETURN)) u_leaf(
   .clk(pg_clk),.rst_n(leaf_rst_n),.su_rq(leaf_rq[h*17+:17]),.su_wq(leaf_wq[h*281+:281]),.su_rr(leaf_rr[h*257+:257]),
   .su_w_done(leaf_done[h]),.lg_rq(lg_rq[h*17+:17]),.lg_wq(lg_wq[h*281+:281]),.lg_rr(lg_rr[h*257+:257]),
   .lg_w_done(lg_w_done[h]),.fault(leaf_fault[h]));
 end
 // ------------------------------------------------------------------ FILL: request, destination delay line, one stage
 localparam integer FD=(MUT==1)?RR-1:RR;
 reg [10:0] fd [0:1][0:RR];          // {v, grp_hi, row9}
 reg [1:0] fr_v; reg [1:0] fr_hi; reg [8:0] fr_row [0:1]; reg [255:0] fr_dat [0:1];
 wire [1:0] cmd_far;
 for(genvar h=0;h<2;h=h+1)begin:g_fill
  wire [29:0] c=vmr_cmd[h*30+:30];
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign su_rq[h*17+:17]={c[29],c[28:13]};
  assign cmd_far[h]=(c[29]&&c[11:9]!=3'(2*G+h))||(w[38]&&!w[37]&&w[35:33]!=3'(2*G+h));
  integer k;
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)begin for(k=0;k<=RR;k=k+1)fd[h][k]<=11'd0; fr_v[h]<=1'b0; end
   else begin
    fd[h][0]<={c[29],c[12],c[8:0]};for(k=1;k<=RR;k=k+1)fd[h][k]<=fd[h][k-1];
    fr_v[h]<=fd[h][FD][10];
   end
  always @(posedge clk_ctl)begin fr_hi[h]<=fd[h][FD][9];fr_row[h]<=fd[h][FD][8:0];fr_dat[h]<=su_rr[h*257+:256];end
 end
 // ------------------------------------------------------------------ COLLPORT inject: stream pin slots -> port-5 reads
 wire [3:0] ij_v;                     // per group {hi,h}: inject read of this slice at this serial edge
 wire [35:0] ij_row;                  // ij_row[9*grp+:9]
 wire ij_bad;
 if(COLLPORT!=0)begin:g_inj
  reg [1:0] sp; reg [1:0] sq;
  always @(posedge pg_clk or negedge bridge_rst_n) if(!bridge_rst_n) sp<=2'd0; else sp<=sp+2'd1;
  always @(posedge clk_ctl or negedge bridge_rst_n) if(!bridge_rst_n) sq<=2'd0; else sq<=(sq==2'd2)?2'd0:sq+2'd1;
  reg [161:0] slot [0:3];
  always @(posedge pg_clk) slot[sp] <= {inj_rd, inj_addr};
  wire [1:0] rs = ((sq==2'd1)?2'd0:(sq==2'd2)?2'd1:2'd3) + ((MUT==8)?2'd1:2'd0);
  wire [161:0] ij = slot[rs];
  reg [3:0] v; reg [35:0] row; reg bad; integer k,gg;
  always @* begin
   v=0; row=0; bad=0;
   for(k=0;k<4;k=k+1) begin : dec
    reg [39:0] a, lo; reg on; reg [1:0] grp;
    a = ij[40*k+:40]; lo = ij[80*(k/2)+:40];
    on = ij[160+(k/2)] && !(B39_NOOP!=0 && lo[39] && MUT!=9) && a[5:4]==2'(G);
    grp = {a[6],a[3]};
    if(on) begin
     if(v[grp] && row[9*grp+:9]!=a[15:7]) bad=1'b1;
     v[grp]=1'b1; row[9*grp+:9]=a[15:7];
    end
   end
  end
  assign ij_v=v; assign ij_row=row; assign ij_bad=bad;
 end else begin:g_no_inj
  assign ij_v=4'd0; assign ij_row=36'd0; assign ij_bad=1'b0;
 end
 // ------------------------------------------------------------------ store banks
 wire [32*192-1:0] bank_q;
 wire [31:0] st_inj_drain;
 wire [31:0] st_conflict,st_id_fault;
 // drain store-group reads: port h reads group (h, grp_hi) = slice lanes 8h + 16*grp_hi .. +7
 wire [1:0] dr_v,dr_hi; wire [8:0] dr_row [0:1];
 for(genvar h=0;h<2;h=h+1)begin:g_dr
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign dr_v[h]=w[38]&&!w[37]; assign dr_hi[h]=w[36]; assign dr_row[h]=w[32:24];
 end
 for(genvar n=0;n<32;n=n+1)begin:g_bank
  localparam integer L=lid(n),H=(n/8)%2,HI=n/16,K=n%8;
  wire [53:0] ra; wire [5:0] rv; wire [191:0] q;
  for(genvar p=0;p<4;p=p+1)begin:g_read
   wire [23:0] a=rd_addr[(n*4+p)*24+:24];
   assign ra[p*9+:9]={a[17:16],a[13:7]}; assign rv[p]=rd_re[n*4+p]&&rd_src[n*8+2*p+:2]==2'd0;
  end
  assign ra[4*9+:9]={vi_addr[n*24+16+:2],vi_addr[n*24+7+:7]}; assign rv[4]=vi_re[n]; assign vi_q[n*32+:32]=q[4*32+:32];
  wire drn=dr_v[H]&&dr_hi[H]==1'(HI);
  wire ijn=ij_v[2*HI+H];
  assign ra[5*9+:9]=ijn?ij_row[9*(2*HI+H)+:9]:dr_row[H]; assign rv[5]=drn||ijn;
  assign st_inj_drain[n]=drn&&ijn;
  assign bank_q[n*192+:192]=q;
  assign inj_q[n*32+:32]=q[5*32+:32];
  wire lw=vm_we[n]|kv_we[n];
  wire [23:0] la=vm_we[n]?vm_waddr[n*24+:24]:kv_waddr[n*24+:24];
  wire [31:0] ldat=vm_we[n]?vm_wdata[n*32+:32]:kv_wdata[n*32+:32];
  wire fw=fr_v[H]&&fr_hi[H]==1'(HI);
  wire dwn=(COLLPORT!=0)&&dw_v[HI];
  wire [8:0] dwr=dw_row[9*HI+:9];
  wire [31:0] dwd=dw_d[512*HI+32*((MUT==10)?15-(n%16):(n%16))+:32];
  assign st_conflict[n]=(fw&&lw)||(fw&&dwn)||(dwn&&lw);
  reg idf; integer p2;
  always @*begin
   idf=lw&&(la[6:0]!=7'(L)||la[15:14]!=2'(QID));
   for(p2=0;p2<4;p2=p2+1)if(rv[p2]&&(rd_addr[(n*4+p2)*24+:7]!=7'(L)||rd_addr[(n*4+p2)*24+14+:2]!=2'(QID)))idf=1;
  end
  assign st_id_fault[n]=idf;
  ot_hbm_su_static_pinned_bank__d4g_pgslice #(.READERS(6),.RB(9)) u_bank(.clk(clk_bank[n]),.clk_rd(clk_bank[n]),.clk_ws(clk_bank[n]),.clk_macro(clk_bank_macro[n*6+:6]),.rst_n(rst_n),.read_v(rv),.read_addr(ra),
   .read_data(q),.read_return(),.write_v(lw|fw|dwn),.write_addr(fw?fr_row[H]:dwn?dwr:{la[17:16],la[13:7]}),
   .write_data(fw?fr_dat[H][K*32+:32]:dwn?dwd:ldat));
 end
 // ------------------------------------------------------------------ RF broadcast into lane operands
 wire [4*32-1:0] rf_bword_u; wire [4*9-1:0] rf_bcmd_u; wire [255:0] rf_dsec_u;   // as used (local copy or pins)
 if(RF_LOCAL)begin:g_rf_local
  // local copy beside the bank group: data words without reset; command valids reset (fault checks stay clean)
  reg [4*32-1:0] rf_bword_l; reg [255:0] rf_dsec_l; reg [4*8-1:0] rf_badr_l; reg [3:0] rf_bv_l; integer vb;
  always @(posedge clk_ctl)begin
   rf_bword_l<=rf_bword; rf_dsec_l<=rf_dsec;
   for(vb=0;vb<4;vb=vb+1)rf_badr_l[vb*8+:8]<=rf_bcmd[vb*9+:8];
  end
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)rf_bv_l<=4'd0;
   else for(vb=0;vb<4;vb=vb+1)rf_bv_l[vb]<=rf_bcmd[vb*9+8];
  wire [4*9-1:0] rf_bcmd_l={rf_bv_l[3],rf_badr_l[24+:8],rf_bv_l[2],rf_badr_l[16+:8],rf_bv_l[1],rf_badr_l[8+:8],rf_bv_l[0],rf_badr_l[0+:8]};
  assign rf_bword_u=rf_bword_l; assign rf_bcmd_u=rf_bcmd_l; assign rf_dsec_u=rf_dsec_l;
 end else begin:g_rf_direct
  assign rf_bword_u=rf_bword; assign rf_bcmd_u=rf_bcmd; assign rf_dsec_u=rf_dsec;
 end
 reg [31:0] rf_src_bad;
 for(genvar n=0;n<32;n=n+1)begin:g_opmux
  wire [3:0] is_rf;
  reg [3:0] src1_a,src1_b,src1_c;      // the stream's source code 1 rides the read: request n -> select held n+2..n+3
  for(genvar p=0;p<4;p=p+1)begin:g_p
   assign is_rf[p]=rd_re[n*4+p]&&rd_src[n*8+2*p+:2]==2'd1;
   assign rd_q[(n*4+p)*32+:32]=((MUT==4)?src1_b[p]:src1_c[p])?rf_bword_u[p*32+:32]:bank_q[n*192+p*32+:32];
  end
  always @(posedge clk_lane[n*8])begin src1_a<=is_rf;src1_b<=src1_a;src1_c<=src1_b;end
  integer p2;
  always @*begin
   rf_src_bad[n]=0;
   for(p2=0;p2<4;p2=p2+1)begin
    if(rd_re[n*4+p2]&&rd_src[n*8+2*p2+1])rf_src_bad[n]=1;
    if(is_rf[p2]&&(!rf_bcmd_u[p2*9+8]||rd_addr[(n*4+p2)*24+:24]!={16'd0,rf_bcmd_u[p2*9+:8]}))rf_src_bad[n]=1;
   end
  end
 end
 // ------------------------------------------------------------------ DRAIN: delay line + registered 2:1 group select
 reg [26:0] dd [0:1][0:2];           // {v, src, grp_hi, sector16, mask8}
 wire [1:0] rf_drain_bad;
 for(genvar h=0;h<2;h=h+1)begin:g_drain
  wire [38:0] w=vmw_cmd[h*39+:39];
  assign rf_drain_bad[h]=w[38]&&w[37]&&!(G==0&&h==0);
  integer k;
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)begin for(k=0;k<3;k=k+1)dd[h][k]<=27'd0; end
   else begin dd[h][0]<={w[38],w[37],w[36],w[23:0]};dd[h][1]<=dd[h][0];dd[h][2]<=dd[h][1]; end
  wire hi=dd[h][2][24]^((MUT==2)?1'b1:1'b0);
  reg [255:0] sel; integer kk;
  always @*begin
   for(kk=0;kk<8;kk=kk+1)sel[kk*32+:32]=bank_q[(8*h+16*hi+kk)*192+5*32+:32];
   if(dd[h][2][25])sel=rf_dsec_u;
  end
  reg wq_v; reg [279:0] wq_p;
  always @(posedge clk_ctl or negedge rst_n)
   if(!rst_n)wq_v<=1'b0; else wq_v<=dd[h][2][26];
  always @(posedge clk_ctl)wq_p<={dd[h][2][23:8],sel,dd[h][2][7:0]};
  assign su_wq[h*281+:281]={wq_v,wq_p};
 end
 // ------------------------------------------------------------------ reducer operand stage
 // red_sel = {v[11], op[10:8], osel[7], lane[6:0]}; lane L is in this slice iff (L mod 64) / 16 == G
 wire [6:0] rl=red_sel[6:0];
 wire mine=red_sel[11]&&!red_sel[7]&&(rl[5:4]==2'(G));
 wire [4:0] rn={rl[6],rl[3:0]};
 wire ext=red_sel[10:8]==3'd0||red_sel[10:8]==3'd1||red_sel[10:8]==3'd3;
 wire red_bad=mine&&ext&&!ro_v[rn];
 always @(posedge clk_ctl)slice_x<=ro_x[rn*32+:32];
 // ------------------------------------------------------------------ sticky fault
 always @(posedge clk_ctl or negedge rst_n)
  if(!rst_n)fault<=1'b0;
  else if((|l_fault)||(|l_coll)||(|leaf_fault)||(|bridge_fault)||(|st_conflict)||(|st_id_fault)||(|cmd_far)||(|rf_src_bad)||
          (|rf_drain_bad)||red_bad||side_fault||(|st_inj_drain)||ij_bad)fault<=1'b1;
endmodule
`default_nettype wire

// Scoped source: rtl/hbm_accel/generic/adapters/static_su/top/ot_hbm_su_static_pgslice_lg.sv
`timescale 1ns/1ps
`default_nettype none
// SU bank-group slice WITH its two LG taps folded in (coordinator 0db 10-17: lg_static_bank folds into its consumer
// tile; no separate tap slots). = unchanged ot_hbm_su_static_pgslice__d4g_pgslice + ot_hbm_vm_lg_pair_tap__d4g_pgslice (SU level, return
// edges READ_RETURN/WRITE_RETURN = the slice's own 10/7, no rret/wret straps). Ports: every pgslice port unchanged
// except lg_* which now face the VM bank (= the taps' near side); new lg_read/lg_write (calendar local selects),
// far_rq/far_wq (from the SFU-level taps) and far_rr/far_w_done (to them); lg_fault = OR of the two taps.
// The taps run on pg_clk (the slice's VM bank leaf clock). Generated from the pgslice port list (one-off; static).
// RSYNC (HBM-SU3 2026-10-17, default 1): the serial power-on reset rst_n reaches the stream-domain taps and the
// slice's two VM bank leaves through 1-bit serial->stream synchronisers (clk_ctl source flop + two pg_clk flops): the
// taps in the hardened leaf ot_hbm_su_static_pg_lg_tap, the leaves by pgslice PG_RSYNC=1. RSYNC=0 = the r8b structure
// (one pg_clk flop of rst_n for the taps, raw async rst_n on the leaves), kept only as the bench reference.
// Datapath edges unchanged; reset assert/release on the stream side move to the synchronised edges.
module ot_hbm_su_static_pgslice_lg #(
 parameter integer QID=0,G=0,READ_RETURN=10,WRITE_RETURN=7,FETCH_EXTRA_EDGES=2,MLAT=3,ALAT=3,LEAF=0,MUT=0,MULTIRATE=0,
 parameter integer PIN_REG=0,
 parameter integer COLLPORT=0,
 parameter integer B39_NOOP=(QID==0),
 parameter integer RF_LOCAL=0,
 parameter integer RSYNC=1,
 parameter integer RSYNC_MUT=0
)(
 input wire pg_clk,
 input wire [255:0] clk_lane,
 input wire [127:0] clk_insert,
 input wire [31:0] rst_lane_n,
 input wire [3:0] clk_bcast,
 input wire [3:0] rst_bcast_n,
 input wire [31:0] clk_bank,
 input wire [191:0] clk_bank_macro,
 input wire clk_ctl,
 input wire [5:0] clk_side,
 input wire rst_n,
 input wire bridge_rst_n,
 input wire [1741:0] control,
 input wire [2*30-1:0] vmr_cmd,
 input wire [2*39-1:0] vmw_cmd,
 input wire [4*32-1:0] rf_bword,
 input wire [4*9-1:0] rf_bcmd,
 input wire [255:0] rf_dsec,
 input wire [11:0] red_sel,
 output wire [31:0] slice_x,
 input wire [1:0] inj_rd,
 input wire [159:0] inj_addr,
 output wire [1023:0] inj_q,
 input wire [1:0] dw_v,
 input wire [17:0] dw_row,
 input wire [1023:0] dw_d,
 output wire fault,
 output wire [33:0] lg_rq,
 output wire [561:0] lg_wq,
 input wire [513:0] lg_rr,
 input wire [1:0] lg_w_done,
 input wire [1:0] lg_read,lg_write,
 input wire [33:0] far_rq,
 input wire [561:0] far_wq,
 output wire [513:0] far_rr,
 output wire [1:0] far_w_done,
 output wire lg_fault
);
 wire [33:0] s_rq; wire [561:0] s_wq; wire [513:0] s_rr; wire [1:0] s_done;
 ot_hbm_su_static_pgslice__d4g_pgslice #(.QID(QID),.G(G),.READ_RETURN(READ_RETURN),.WRITE_RETURN(WRITE_RETURN),.FETCH_EXTRA_EDGES(FETCH_EXTRA_EDGES),.MLAT(MLAT),.ALAT(ALAT),.LEAF(LEAF),.MUT(MUT),.MULTIRATE(MULTIRATE),.PIN_REG(PIN_REG),.COLLPORT(COLLPORT),.B39_NOOP(B39_NOOP),.RF_LOCAL(RF_LOCAL),.PG_RSYNC(RSYNC)) u_slice(
  .pg_clk(pg_clk),
  .clk_lane(clk_lane),
  .clk_insert(clk_insert),
  .rst_lane_n(rst_lane_n),
  .clk_bcast(clk_bcast),
  .rst_bcast_n(rst_bcast_n),
  .clk_bank(clk_bank),
  .clk_bank_macro(clk_bank_macro),
  .clk_ctl(clk_ctl),
  .clk_side(clk_side),
  .rst_n(rst_n),
  .bridge_rst_n(bridge_rst_n),
  .control(control),
  .vmr_cmd(vmr_cmd),
  .vmw_cmd(vmw_cmd),
  .rf_bword(rf_bword),
  .rf_bcmd(rf_bcmd),
  .rf_dsec(rf_dsec),
  .red_sel(red_sel),
  .slice_x(slice_x),
  .lg_rq(s_rq),
  .lg_wq(s_wq),
  .lg_rr(s_rr),
  .lg_w_done(s_done),
  .inj_rd(inj_rd),
  .inj_addr(inj_addr),
  .inj_q(inj_q),
  .dw_v(dw_v),
  .dw_row(dw_row),
  .dw_d(dw_d),
  .fault(fault));
 if(RSYNC)begin:g_tap
