        for (k = 0; k < KCP; k = k + 1) begin : g_c
            ot_hdc_mul_kcp48__d4g_pgslice u_k (.clk(clk), .rst_n(rst_n),
`ifdef NEGK
                .d({a_n ^ ((k == 1) ? 24'd1 : 24'd0), b_n}),   // bench negative control only
`else
